        createStructurePatterns();
    }

    @Override
    public void onLoad() {
        super.onLoad();
        if (!isRemote()) {
            // run a structure check on the first tick
            ((ServerLevel) getLevel()).getServer().tell(new TickTask(2, this::checkAndFormStructure));
        }
    }

    @Override
    public void onUnload() {
        super.onUnload();
        if (getLevel() instanceof ServerLevel serverLevel) {
            for (var pattern : patternStates.values()) {
                MultiblockWorldSavedData.getOrCreate(serverLevel).removeMapping(pattern);
            }
        }
        invalidateAllStructures();
    }

    public Map<String, IBlockPattern> getStructurePatterns() {
        return structurePatterns.row(this.getDefinition());
    }

    public void setFlipped(boolean flipped) {
        isFlipped = flipped;
        syncDataHolder.markClientSyncFieldDirty("isFlipped");
    }

    @SuppressWarnings("unused")
    @ClientFieldChangeListener(fieldName = "partPositions")
    protected void onPartsUpdated() {
        parts.clear();
        for (var pos : partPositions) {
            if (getMachine(getLevel(), pos) instanceof MultiblockPartMachine part) {
                parts.add(part);
            }
        }
    }

    /**
     * Gets the first trait (trait with highest priority) of a specified class from this multiblock's parts.<br>
     * Also includes traits that are a subtype of the specified class.
     *
     * @param type The trait type to get.
     * @return The trait, or null if no traits of the given type are present.
     */
    public <T extends MachineTrait> @Nullable T getTraitFromParts(Class<T> type) {
        T trait = null;
        for (var part : getParts()) {
            T partTrait = part.getTrait(type);
            if (partTrait != null && (trait == null || partTrait.getTraitPriority() > trait.getTraitPriority()))
                trait = partTrait;
        }
        return trait;
    }

    /**
     * Get all traits with the specified class from this multiblock's parts.<br>
     * Also includes traits that are a subtype of the specified class.
     *
     * @param type The trait type to get
     * @return An unmodifiable list containing all traits of the specified type.
     */
    public <T extends MachineTrait> List<T> getTraitsFromParts(Class<T> type) {
        List<T> traits = new ObjectArrayList<>();
        for (var part : getParts()) {
            traits.addAll(part.getTraits(type));
        }
        return Collections.unmodifiableList(traits);
    }

    protected void updatePartPositions() {
        this.partPositions = this.parts.isEmpty() ? new BlockPos[0] :
                this.parts.stream().map(BlockEntity::getBlockPos).toArray(BlockPos[]::new);
        syncDataHolder.markClientSyncFieldDirty("partPositions");
    }

    public List<MultiblockPartMachine> getParts() {
        // for the client side, when the chunk unloaded
        if (this.parts.size() != this.partPositions.length) {
            this.parts.clear();
            for (BlockPos pos : this.partPositions) {
                if (getMachine(getLevel(), pos) instanceof MultiblockPartMachine part) {
                    this.parts.add(part);
                }
            }
        }
        return this.parts;
    }

    /**
     * The instance of {@link ParallelHatchPartMachine} attached to this controller.
     * <p>
     * Note that this will return a singular instance, and will not account for multiple attached IParallelHatches
     *
     * @return an {@link Optional} of the attached IParallelHatch, empty if one is not attached
     */
    public Optional<ParallelHatchPartMachine> getParallelHatch() {
        return Optional.ofNullable(parallelHatch);
    }

    //////////////////////////////////////
    // *** Multiblock LifeCycle ***//
    //////////////////////////////////////

    public void checkAndFormStructure() {
        if (!(getLevel() instanceof ServerLevel serverLevel)) return;
        if (isRemoved()) return;
        for (var entry : patternStates.entrySet()) {
            String name = entry.getKey();
            PatternState patternState = getPatternState(name);
            boolean formed = name.equals(DEFAULT_STRUCTURE) ? isFormed : patternState.isFormed();
            if (!formed || patternState.hasErrors() ||
                    patternState.getState() == PatternState.CheckState.UNINITIALIZED) {
                if (!patternState.getState().isValid()) {
                    checkStructurePattern(name);
                }
                if (patternState.getState().isValid()) {
                    formStructure(name);
                }
                MultiblockWorldSavedData.getOrCreate(serverLevel).addMapping(patternState);

            }
        }
    }

    /**
     * Whether the specific part should be added to the part list
     */
    public boolean shouldAddPartToController(MultiblockPartMachine part) {
        return true;
    }

    /**
     * Returns a list of all substructures this multiblock has.
     *
     * @return set of substructures used by controller
     */
    public Set<String> getStructureNames() {
        return structurePatterns.row(this.getDefinition()).keySet();
    }

    /**
     * The {@link MultiblockMachineDefinition} of this multiblock.
     *
     * @return The {@link MultiblockMachineDefinition}
     */
    @Override
    public MultiblockMachineDefinition getDefinition() {
        return (MultiblockMachineDefinition) super.getDefinition();
    }

    /**
     * Get structure pattern.
     * You can override it to create dynamic patterns.
     */
    public IBlockPattern getDefaultStructurePattern() {
        return getDefinition().getStructurePatterns().get(DEFAULT_STRUCTURE).get();
    }

    /**
     * Creates the default pattern and pattern state and populates the state maps
     */
    public void createStructurePatterns() {
        getDefinition().getStructurePatterns().forEach((name, pattern) -> {
            patternStates.put(name, new PatternState());
            structurePatterns.put(this.getDefinition(), name, pattern.get());
        });
        getSyncDataHolder().markClientSyncFieldDirty("patternStates");
    }

    public PatternState getDefaultPatternState() {
        return getPatternState(DEFAULT_STRUCTURE);
    }

    public PatternState getPatternState(String name) {
        return this.patternStates.get(name);
    }

    public PatternState checkDefaultStructurePattern() {
        return checkStructurePattern(DEFAULT_STRUCTURE);
    }

    public PatternState checkStructurePattern(String structureName) {
        IBlockPattern pattern = getSubstructurePattern(structureName);
        PatternState state = getPatternState(structureName);
        if (pattern == null || !state.shouldUpdate() || getLevel() == null) return state;

        state.setController(this, getBlockPos());
        pattern.checkPatternFastAt(getLevel(), state, getBlockPos(), getFrontFacing(), getUpwardsFacing(),
                allowFlip());

        return state;
    }

    public void formStructure(String substructureName) {
        var patternState = getPatternState(substructureName);
        patternState.setFormed(true);
        if (substructureName.equals(DEFAULT_STRUCTURE)) {
            isFormed = true;
            getSyncDataHolder().markClientSyncFieldDirty("isFormed");
        }

        if (!patternState.getState().isValid()) {
            if (patternState.isFormed()) {
                invalidateStructure(substructureName);
            }
        }

        if (patternState.isFormed()) {
            if (patternState.getState() == PatternState.CheckState.VALID_UNCACHED) {
                forEachMultiPart(substructureName, part -> {
                    if (parts.contains(part)) return true;

                    if (part.hasController(getBlockPos()) && !part.canShared(this, substructureName)) {
                        invalidateStructure(substructureName);
                        return false;
                    }

                    if (shouldAddPartToController(part)) {
                        this.parts.add(part);
                    }
                    return true;
                });

                this.parts.sort(getDefinition().getPartSorter().apply(this));
                for (var part : parts) {
                    if (part instanceof ParallelHatchPartMachine pHatch) {
                        this.parallelHatch = pHatch;
                    }
                    part.addedToController(this, substructureName);
                }
                updatePartPositions();

                patternState.setFormed(true);
                if (substructureName.equals(DEFAULT_STRUCTURE)) {
                    this.isFormed = true;
                    getSyncDataHolder().markClientSyncFieldDirty("isFormed");
                }
                setFlipped(patternState.isFlipped(), patternState);

                for (var trait : getAllTraits()) {
                    if (trait instanceof MultiblockMachineTrait multiblockMachineTrait)
                        multiblockMachineTrait.onStructureFormed(substructureName);
                }
            }
            return;
        }

        boolean valid = forEachMultiPart(substructureName,
                part -> !part.hasController(getBlockPos()) || part.canShared(this, substructureName));

        if (!valid) return;

        patternState.setFormed(true);
        if (substructureName.equals(DEFAULT_STRUCTURE)) {
            isFormed = true;
            getSyncDataHolder().markClientSyncFieldDirty("isFormed");
            MachineRenderState renderState = getRenderState();
            if (renderState.hasProperty(GTMachineModelProperties.IS_FORMED)) {
                setRenderState(renderState.setValue(GTMachineModelProperties.IS_FORMED, true));
            }
        }
        setFlipped(patternState.isFlipped(), patternState);
    }

    public void setFlipped(boolean flipped, PatternState state) {
        boolean flip = state.isActualFlipped();
        if (flip != flipped) {
            state.setActualFlipped(flipped);
            this.isFlipped = flipped;
            notifyBlockUpdate();
        }
    }

    public void invalidateAllStructures() {
        for (String name : patternStates.keySet()) {
            parts.removeIf(part -> {
                if (name.equals(part.getSubstructureName())) {
                    part.removedFromController(this);
                    return true;
                }
                return false;
            });
        }
    }

    public void invalidateStructure() {
        invalidateStructure(DEFAULT_STRUCTURE);
        isFormed = false;
        getSyncDataHolder().markClientSyncFieldDirty("isFormed");
    }

    public void invalidateStructure(String name) {
        var pState = patternStates.get(name);

        MachineRenderState renderState = getRenderState();
        if (renderState.hasProperty(GTMachineModelProperties.IS_FORMED)) {
            setRenderState(renderState.setValue(GTMachineModelProperties.IS_FORMED, false));
        }
        parts.removeIf(part -> {
            if (name.equals(part.getSubstructureName())) {
                part.removedFromController(this);
                return true;
            }
            return false;
        });
        pState.setFormed(false);
        if (name.equals(DEFAULT_STRUCTURE)) {
            isFormed = false;
            parallelHatch = null;
            getSyncDataHolder().markClientSyncFieldDirty("isFormed");
        }
        updatePartPositions();

        for (var trait : getAllTraits()) {
            if (trait instanceof MultiblockMachineTrait multiblockMachineTrait)
                multiblockMachineTrait.onStructureInvalid(name);
        }
    }

    protected void invalidateStructureCaches() {
        for (var pState : patternStates.values()) {
            pState.getCache().clear();
        }
    }

    @Nullable
    public IBlockPattern getSubstructurePattern(String name) {
        return structurePatterns.get(this.getDefinition(), name);
    }

    protected final boolean forEachMultiPart(String name, Predicate<MultiblockPartMachine> action) {
        var cache = patternStates.get(name).getCache();
        for (BlockInfo info : cache.values()) {
            if (info.getBlockEntity() instanceof MultiblockPartMachine part) {
                if (!action.test(part)) return false;
            }
        }
        return true;
    }

    protected void forEachFormed(String name, BiConsumer<BlockInfo, BlockPos.MutableBlockPos> action) {
        var cache = patternStates.get(name).getCache();
        var pos = new BlockPos.MutableBlockPos();
        for (var entry : cache.long2ObjectEntrySet()) {
            action.accept(entry.getValue(), pos.set(entry.getLongKey()));
        }
    }

    /**
     * mark multiblockState as unload error first.
     * if it's actually cuz by block breaking.
     * {@link #invalidateStructure()} will be called from
     * {@link PatternState#onBlockStateChanged(BlockPos, BlockState, BlockState)}
     */
    public void onPartUnload() {
        parts.removeIf(BlockEntity::isRemoved);
        updatePartPositions();
    }

    @Override
    public void onRotated(Direction oldFacing, Direction newFacing) {
        if (oldFacing != newFacing && getLevel() instanceof ServerLevel serverLevel) {
            // invalid structure
            invalidateStructureCaches();
            var mwsd = MultiblockWorldSavedData.getOrCreate(serverLevel);
            for (var patternState : patternStates.values()) {
                mwsd.removeMapping(patternState);
            }
            checkAndFormStructure();
        }
    }

    public boolean allowFlip() {
        return getDefinition().isAllowFlip();
    }

    public @Nullable BlockState getPartAppearance(MultiblockPartMachine part, Direction side,
                                                  @Nullable BlockState sourceState,
                                                  @Nullable BlockPos sourcePos) {
        if (isFormed()) {
            return getDefinition().getPartAppearance().apply(this, part, side);
        }
        return null;
    }

    @Override
    public void setUpwardsFacing(Direction upwardsFacing) {
        if (getLevel() == null) return;
        if (!getDefinition().isAllowExtendedFacing()) return;
        BlockState blockState = getBlockState();
        if (blockState.getBlock() instanceof MetaMachineBlock &&
                blockState.getValue(GTBlockStateProperties.UPWARDS_FACING) != upwardsFacing) {
            getLevel().setBlockAndUpdate(getBlockPos(),
                    blockState.setValue(GTBlockStateProperties.UPWARDS_FACING, upwardsFacing));
            if (getLevel() != null && !getLevel().isClientSide) {
                notifyBlockUpdate();
                invalidateStructureCaches();
                checkAndFormStructure();
            }
        }
    }

    @Override
    public void setFrontFacing(Direction facing) {
        super.setFrontFacing(facing);

        if (getLevel() != null && !getLevel().isClientSide) {
            invalidateStructureCaches();
            checkAndFormStructure();
        }
    }

    @Override
    public InteractionResult onUse(ExtendedUseOnContext context) {
        if (!isFormed() && context.getPlayer().isShiftKeyDown() &&
                context.getPlayer().getItemInHand(context.getHand()).isEmpty()) {
            if (isRemote()) {
                Map<BlockPos, BlockInfo> resultStructure = new HashMap<>();
                AbstractStructureHelper structureHelper = null;
                IBlockPattern pattern = getStructurePatterns().get(DEFAULT_STRUCTURE);
                if (pattern instanceof BlockPattern blockPattern) {
                    Int2IntMap slices = new Int2IntArrayMap();
                    for (int i = 0; i < blockPattern.getSlices().length; i++) {
                        slices.put(i, blockPattern.getSlices()[i].getMinRepeats());
                    }
                    structureHelper = AbstractStructureHelper.blockPattern(slices);
                } else if (pattern instanceof ExpandablePattern expandablePattern) {
                    IntList dims = new IntArrayList();
                    if (expandablePattern.getBoundsConstraints() != null) {
                        expandablePattern.getBoundsConstraints().apply().stream()
                                .mapToInt(Pair::left)
                                .forEach(dims::add);
                    }
                    structureHelper = AbstractStructureHelper.expandable(dims);
                }

                if (structureHelper != null) {
                    var info = new MultiblockSchemaInfo(this.getDefinition());
                    info.setIgnorePreviewCount(true);
                    structureHelper.populate(info, resultStructure, pattern,
                            null,
                            getFrontFacing(), getUpwardsFacing(),
                            isFlipped());
                    Long2ReferenceMap<BlockState> blocks = new Long2ReferenceOpenHashMap<>();
                    resultStructure.forEach((pos, state) -> blocks.put(pos.asLong(), state.getBlockState()));
                    MutableSchema schema = new MutableSchema(blocks);
                    BlockPos origin = this.getBlockPos().mutable().move(schema.getControllerPos().multiply(-1));
                    PatternPreviewRenderer.INSTANCE.showPreviewCycleLevel(origin, schema,
                            ConfigHolder.INSTANCE.client.inWorldPreviewDuration * 20);
                }
            }
            return InteractionResult.sidedSuccess(isRemote());
        }
        return super.onUse(context);
    }

    /**
     *
     * @return Whether batching is enabled on this multiblock
     */
    public boolean isBatchEnabled() {
        return false;
    }

    // TODO move to recipe logic
    public void setBatchEnabled(boolean batch) {}

    public Widget<?> getMainTextPanel(PanelSyncManager syncManager) {
        return getMainTextPanel(syncManager, MULTI_UI_TEXT_PANEL_WIDTH, MULTI_UI_TEXT_PANEL_HEIGHT);
    }

    public Widget<?> getMainTextPanel(PanelSyncManager syncManager, int width, int height) {
        var parentWidget = new ParentWidget<>();
        var listWidget = new ListWidget<>();
        listWidget
                .width(width - 6)
                .height(height - 6)
                .childSeparator(Icon.EMPTY_2PX)
                .crossAxisAlignment(Alignment.CrossAxis.START)
                .collapseDisabledChildren()
                .posRel(Alignment.CenterLeft)
                .left(3)
                .top(3);
        parentWidget.size(width, height)
                .background(GTGuiTextures.DISPLAY);

        listWidget.children(getWidgetsForDisplay(syncManager));
        parentWidget.child(listWidget.left(3).top(3));
        return parentWidget;
    }

    /**
     * Can be overridden to just add widgets to the black box in the middle instead of overriding the whole UI.
     * Don't forget to invoke {@code super.getWidgetsForDisplay} to add the default lines (progress, voltage, etc.).
     *
     * @param syncManager the sync manager
     * @return list of widgets to be displayed inside the black box in the middle of a standard multiblock UI
     */
    public List<IWidget> getWidgetsForDisplay(PanelSyncManager syncManager) {
        return new ArrayList<>();
    }

    public boolean allowCircuitSlots() {
        return true;
    }
}

package com.gregtechceu.gtceu.api.machine.multiblock;

import com.gregtechceu.gtceu.api.GTValues;
import com.gregtechceu.gtceu.api.blockentity.BlockEntityCreationInfo;
import com.gregtechceu.gtceu.api.capability.IEnergyContainer;
import com.gregtechceu.gtceu.api.capability.recipe.EURecipeCapability;
import com.gregtechceu.gtceu.api.capability.recipe.IO;
import com.gregtechceu.gtceu.api.capability.recipe.IRecipeHandler;
import com.gregtechceu.gtceu.api.machine.feature.IMuiMachine;
import com.gregtechceu.gtceu.api.machine.feature.IOverclockMachine;
import com.gregtechceu.gtceu.api.machine.feature.ITieredMachine;
import com.gregtechceu.gtceu.api.machine.feature.IVoidable;
import com.gregtechceu.gtceu.api.machine.trait.recipe.RecipeLogic;
import com.gregtechceu.gtceu.api.misc.EnergyContainerList;
import com.gregtechceu.gtceu.api.recipe.GTRecipe;
import com.gregtechceu.gtceu.api.sync_system.annotations.SaveField;
import com.gregtechceu.gtceu.common.mui.GTMultiblockTextUtil;
import com.gregtechceu.gtceu.utils.GTUtil;

import net.minecraft.MethodsReturnNonnullByDefault;

import brachy.modularui.api.widget.IWidget;
import brachy.modularui.factory.PosGuiData;
import brachy.modularui.screen.UISettings;
import brachy.modularui.value.sync.PanelSyncManager;
import brachy.modularui.widget.ParentWidget;
import lombok.Getter;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

import java.util.ArrayList;
import java.util.List;

import javax.annotation.ParametersAreNonnullByDefault;

@ParametersAreNonnullByDefault
@MethodsReturnNonnullByDefault
public class WorkableElectricMultiblockMachine extends WorkableMultiblockMachine
                                               implements IMuiMachine, ITieredMachine, IOverclockMachine, IVoidable {

    // runtime
    protected @Nullable EnergyContainerList energyContainer;
    @Getter
    protected int tier;
    @SaveField
    @Getter
    protected boolean batchEnabled;

    public WorkableElectricMultiblockMachine(BlockEntityCreationInfo info, RecipeLogic recipeLogic) {
        super(info, recipeLogic);
    }

    public WorkableElectricMultiblockMachine(BlockEntityCreationInfo info) {
        super(info);
    }

    //////////////////////////////////////
    // *** Multiblock Lifecycle ***//
    //////////////////////////////////////
    @Override
    public void invalidateStructure(String name) {
        super.invalidateStructure(name);
        this.energyContainer = null;
        this.tier = 0;
    }

    @Override
    public void formStructure(@NotNull String substructureName) {
        super.formStructure(substructureName);
        this.energyContainer = getEnergyContainer();
        this.tier = GTUtil.getFloorTierByVoltage(getMaxVoltage());
    }

    @Override
    public void onPartUnload() {
        super.onPartUnload();
        this.energyContainer = null;
        this.tier = 0;
    }

    @Override
    public void setBatchEnabled(boolean batch) {
        this.batchEnabled = batch;
    }

    //////////////////////////////////////
    // ********** GUI ***********//
    //////////////////////////////////////

    @Override
    public void buildMainUI(ParentWidget<?> mainWidget, PosGuiData guiData, PanelSyncManager syncManager,
                            UISettings settings) {
        mainWidget.child(getMainTextPanel(syncManager).margin(4, 2));
    }

    @Override
    public List<IWidget> getWidgetsForDisplay(PanelSyncManager syncManager) {
        List<IWidget> widgets = new ArrayList<>();

        widgets.add(GTMultiblockTextUtil.addEnergyTierLine(this, syncManager));
        widgets.add(GTMultiblockTextUtil.addEnergyUsageLine(this, syncManager));
        widgets.add(GTMultiblockTextUtil.addEnergyUsageExactLine(this, syncManager));
        widgets.addAll(super.getWidgetsForDisplay(syncManager));
        return widgets;
    }

    //////////////////////////////////////
    // ******** OVERCLOCK *********//
    //////////////////////////////////////
    @Override
    public int getOverclockTier() {
        return getTier();
    }

    @Override
    public int getMaxOverclockTier() {
        return getTier();
    }

    @Override
    public int getMinOverclockTier() {
        return getTier();
    }

    @Override
    public void setOverclockTier(int tier) {}

    @Override
    public long getOverclockVoltage() {
        if (this.energyContainer == null) {
            this.energyContainer = getEnergyContainer();
        }
        long voltage;
        long amperage;
        if (energyContainer.getInputVoltage() > energyContainer.getOutputVoltage()) {
            voltage = energyContainer.getInputVoltage();
            amperage = energyContainer.getInputAmperage();
        } else {
            voltage = energyContainer.getOutputVoltage();
            amperage = energyContainer.getOutputAmperage();
        }

        if (amperage == 1) {
            // amperage is 1 when the energy is not exactly on a tier
            // the voltage for recipe search is always on tier, so take the closest lower tier
            return GTValues.VEX[GTUtil.getFloorTierByVoltage(voltage)];
        } else {
            // amperage != 1 means the voltage is exactly on a tier
            // ignore amperage, since only the voltage is relevant for recipe search
            // amps are never > 3 in an EnergyContainerList
            return voltage;
        }
    }

    //////////////////////////////////////
    // ****** RECIPE LOGIC *******//
    //////////////////////////////////////

    public EnergyContainerList getEnergyContainer() {
        List<IEnergyContainer> containers = new ArrayList<>();
        var handlers = getCapabilitiesFlat(IO.IN, EURecipeCapability.CAP);
        if (handlers.isEmpty()) handlers = getCapabilitiesFlat(IO.OUT, EURecipeCapability.CAP);
        for (IRecipeHandler<?> handler : handlers) {
            if (handler instanceof IEnergyContainer container) {
                containers.add(container);
            }
        }
        return new EnergyContainerList(containers);
    }

    @Override
    public long getMaxVoltage() {
        if (this.energyContainer == null) {
            this.energyContainer = getEnergyContainer();
        }
        if (this.isGenerator()) {
            // Generators
            long voltage = energyContainer.getOutputVoltage();
            long amperage = energyContainer.getOutputAmperage();
            if (amperage == 1) {
                // Amperage is 1 when the energy is not exactly on a tier.
                // The voltage for recipe search is always on tier, so take the closest lower tier.
                // List check is done because single hatches will always be a "clean voltage," no need
                // for any additional checks.
                return GTValues.VEX[GTUtil.getFloorTierByVoltage(voltage)];
            } else {
                return voltage;
            }
        } else {
            // Machines
            long highestVoltage = energyContainer.getHighestInputVoltage();
            if (energyContainer.getNumHighestInputContainers() > 1) {
                // allow tier + 1 if there are multiple hatches present at the highest tier
                int tier = GTUtil.getTierByVoltage(highestVoltage);
                return GTValues.V[Math.min(tier + 1, GTValues.MAX)];
            } else {
                return highestVoltage;
            }
        }
    }

    @Override
    public long getDisplayRecipeVoltage() {
        long voltage = -1;
        var handlers = getCapabilitiesFlat(IO.IN, EURecipeCapability.CAP);
        if (handlers.isEmpty()) handlers = getCapabilitiesFlat(IO.OUT, EURecipeCapability.CAP);
        for (IRecipeHandler<?> handler : handlers) {
            if (handler instanceof IEnergyContainer container) {
                voltage = Math.max(voltage, Math.max(container.getInputVoltage(), container.getOutputVoltage()));
            }
        }
        return voltage;
    }

    @Override
    public long getDisplayGeneratorPower() {
        if (this.isGenerator()) {
            long power = 0;
            var handlers = getCapabilitiesFlat(IO.OUT, EURecipeCapability.CAP);
            for (IRecipeHandler<?> handler : handlers) {
                if (handler instanceof IEnergyContainer container) {
                    power += container.getOutputVoltage() * container.getOutputAmperage();
                }
            }
            return power;
        }
        return -1;
    }

    public long getDisplayWorkingVoltage() {
        return this.isGenerator() ? getDisplayGeneratorPower() : getDisplayRecipeVoltage();
    }

    public long getRecipeEUt() {
        if (!isActive()) return 0L;
        GTRecipe lastRecipe = recipeLogic.getLastUnrolledRecipe();
        if (lastRecipe == null) return 0L;
        return this.isGenerator() ? lastRecipe.getOutputEUt().getTotalEU() : lastRecipe.getInputEUt().getTotalEU();
    }

    /**
     * Is this multiblock a generator?
     * Used for max voltage calculations.
     */
    public boolean isGenerator() {
        return getDefinition().isGenerator();
    }
}

package com.gregtechceu.gtceu.api.machine.multiblock;

import com.gregtechceu.gtceu.api.block.ActiveBlock;
import com.gregtechceu.gtceu.api.block.property.GTBlockStateProperties;
import com.gregtechceu.gtceu.api.blockentity.BlockEntityCreationInfo;
import com.gregtechceu.gtceu.api.capability.recipe.IO;
import com.gregtechceu.gtceu.api.capability.recipe.IRecipeHandler;
import com.gregtechceu.gtceu.api.capability.recipe.RecipeCapability;
import com.gregtechceu.gtceu.api.machine.feature.IMufflableMachine;
import com.gregtechceu.gtceu.api.machine.feature.IRecipeLogicMachine;
import com.gregtechceu.gtceu.api.machine.multiblock.part.MultiblockPartMachine;
import com.gregtechceu.gtceu.api.machine.property.GTMachineModelProperties;
import com.gregtechceu.gtceu.api.machine.trait.feature.IRecipeLogicModifierTrait;
import com.gregtechceu.gtceu.api.machine.trait.recipe.IRecipeHandlerTrait;
import com.gregtechceu.gtceu.api.machine.trait.recipe.RecipeHandlerList;
import com.gregtechceu.gtceu.api.machine.trait.recipe.RecipeLogic;
import com.gregtechceu.gtceu.api.recipe.GTRecipe;
import com.gregtechceu.gtceu.api.recipe.GTRecipeType;
import com.gregtechceu.gtceu.api.sync_system.annotations.SaveField;
import com.gregtechceu.gtceu.api.sync_system.annotations.SyncToClient;
import com.gregtechceu.gtceu.client.model.machine.MachineRenderState;
import com.gregtechceu.gtceu.common.machine.trait.CleanroomReceiverTrait;
import com.gregtechceu.gtceu.common.mui.GTMultiblockTextUtil;
import com.gregtechceu.gtceu.utils.ISubscription;

import net.minecraft.core.BlockPos;
import net.minecraft.world.level.block.Block;

import brachy.modularui.api.widget.IWidget;
import brachy.modularui.value.sync.PanelSyncManager;
import it.unimi.dsi.fastutil.longs.LongOpenHashSet;
import it.unimi.dsi.fastutil.longs.LongSet;
import lombok.Getter;
import lombok.Setter;
import org.jetbrains.annotations.ApiStatus;
import org.jetbrains.annotations.MustBeInvokedByOverriders;
import org.jetbrains.annotations.Nullable;
import org.jetbrains.annotations.VisibleForTesting;

import java.util.*;

/**
 * The base class for multiblocks with recipe logic.
 */
public abstract class WorkableMultiblockMachine extends MultiblockControllerMachine
                                                implements IRecipeLogicMachine, IMufflableMachine {

    @Getter
    protected final CleanroomReceiverTrait cleanroomReceiver;
    @Getter
    @SaveField
    @SyncToClient
    public final RecipeLogic recipeLogic;
    @Getter
    private final GTRecipeType[] recipeTypes;
    @Getter
    @Setter
    @SaveField
    private int activeRecipeType;
    @Getter
    protected final Map<IO, List<RecipeHandlerList>> capabilitiesProxy;
    @Getter
    protected final Map<IO, Map<RecipeCapability<?>, List<IRecipeHandler<?>>>> capabilitiesFlat;
    protected final List<ISubscription> traitSubscriptions;
    @Getter
    @SaveField
    @SyncToClient
    protected boolean isMuffled;
    protected boolean previouslyMuffled = true;
    @Nullable
    @Getter
    protected LongSet activeBlocks;

    @Getter
    @SaveField
    @SyncToClient
    protected VoidingMode voidingMode = VoidingMode.VOID_NONE;

    public WorkableMultiblockMachine(BlockEntityCreationInfo info,
                                     RecipeLogic recipeLogic) {
        super(info);
        this.recipeTypes = getDefinition().getRecipeTypes();
        this.activeRecipeType = 0;
        this.cleanroomReceiver = attachTrait(new CleanroomReceiverTrait());
        this.recipeLogic = attachTrait(recipeLogic);
        this.recipeLogic.setKeepSubscribing(false);
        this.capabilitiesProxy = new EnumMap<>(IO.class);
        this.capabilitiesFlat = new EnumMap<>(IO.class);
        this.traitSubscriptions = new ArrayList<>();
    }

    public WorkableMultiblockMachine(BlockEntityCreationInfo info) {
        this(info, new RecipeLogic());
    }

    public void setMuffled(boolean muffled) {
        isMuffled = muffled;
        syncDataHolder.markClientSyncFieldDirty("isMuffled");
    }

    //////////////////////////////////////
    // ***** Initialization ******//
    //////////////////////////////////////

    @Override
    public void onUnload() {
        super.onUnload();
        traitSubscriptions.forEach(ISubscription::unsubscribe);
        traitSubscriptions.clear();
    }

    //////////////////////////////////////
    // *** Multiblock LifeCycle ***//
    //////////////////////////////////////
    @Override
    @MustBeInvokedByOverriders
    public void formStructure(String substructureName) {
        super.formStructure(substructureName);
        // attach parts' traits
        var cache = patternStates.get(substructureName).getCache();
        for (var entry : cache.long2ObjectEntrySet()) {
            if (entry.getValue().getBlockState().getBlock() instanceof ActiveBlock) {
                if (activeBlocks == null) activeBlocks = new LongOpenHashSet();
                activeBlocks.add(entry.getLongKey());
            }
        }

        capabilitiesProxy.clear();
        capabilitiesFlat.clear();
        traitSubscriptions.forEach(ISubscription::unsubscribe);
        traitSubscriptions.clear();
        for (MultiblockPartMachine part : getParts()) {

            var handlerLists = part.getRecipeHandlers();
            for (var handlerList : handlerLists) {
                this.addHandlerList(handlerList);
                traitSubscriptions.add(handlerList.subscribe(recipeLogic::updateTickSubscription));
            }
        }

        // attach self traits
        Map<IO, List<IRecipeHandler<?>>> ioTraits = new EnumMap<>(IO.class);
        for (var trait : getTraitHolder().getTraitsByInterface(IRecipeHandlerTrait.class)) {
            ioTraits.computeIfAbsent(trait.getHandlerIO(), i -> new ArrayList<>()).add(trait);
        }

        for (var entry : ioTraits.entrySet()) {
            var handlerList = RecipeHandlerList.of(entry.getKey(), entry.getValue());
            this.addHandlerList(handlerList);
            traitSubscriptions.add(handlerList.subscribe(recipeLogic::updateTickSubscription));
        }
        // schedule recipe logic
        recipeLogic.updateTickSubscription();
    }

    @Override
    @MustBeInvokedByOverriders
    public void invalidateStructure(String name) {
        super.invalidateStructure(name);
        updateActiveBlocks(false);
        activeBlocks = null;
        capabilitiesProxy.clear();
        capabilitiesFlat.clear();
        traitSubscriptions.forEach(ISubscription::unsubscribe);
        traitSubscriptions.clear();
        // reset recipe Logic
        recipeLogic.resetRecipeLogic();
    }

    @Override
    public void onPartUnload() {
        super.onPartUnload();
        updateActiveBlocks(false);
        activeBlocks = null;
        capabilitiesProxy.clear();
        capabilitiesFlat.clear();
        traitSubscriptions.forEach(ISubscription::unsubscribe);
        traitSubscriptions.clear();
        // fine some parts invalid now.
        // but we shouldn't reset recipe logic rn.
        // if it's due to chunk unload, we should just wait for it to be valid again.
        recipeLogic.updateTickSubscription();
    }

    //////////////////////////////////////
    // ****** RECIPE LOGIC *******//
    //////////////////////////////////////

    @Override
    public void clientTick() {
        super.clientTick();
        if (previouslyMuffled != isMuffled) {
            previouslyMuffled = isMuffled;

            recipeLogic.updateSound();
        }
    }

    @Nullable
    @Override
    @MustBeInvokedByOverriders
    public GTRecipe doModifyRecipe(GTRecipe recipe) {
        recipe = self().getDefinition().getRecipeModifier().applyModifier(self(), recipe);
        if (recipe == null) return null;

        for (MultiblockPartMachine part : getParts()) {
            recipe = part.modifyRecipe(recipe);
            if (recipe == null) return null;
        }

        for (var rlTrait : self().getTraitHolder().getTraitsByInterface(IRecipeLogicModifierTrait.class)) {
            recipe = rlTrait.modifyRecipe(recipe);
            if (recipe == null) return null;
        }
        return recipe;
    }

    public void updateActiveBlocks(boolean active) {
        if (activeBlocks != null) {
            for (long pos : activeBlocks) {
                var blockPos = BlockPos.of(pos);
                var blockState = getLevel().getBlockState(blockPos);
                if (blockState.hasProperty(GTBlockStateProperties.ACTIVE)) {
                    var newState = blockState.setValue(GTBlockStateProperties.ACTIVE, active);
                    if (newState != blockState) {
                        getLevel().setBlock(blockPos, newState, Block.UPDATE_CLIENTS | Block.UPDATE_KNOWN_SHAPE);
                    }
                }
            }
        }
    }

    @Override
    public void recipeLogicStatusChanged(RecipeLogic.Status oldStatus, RecipeLogic.Status newStatus) {
        IRecipeLogicMachine.super.recipeLogicStatusChanged(oldStatus, newStatus);
        if (shouldUpdateActiveBlocks()) {
            updateActiveBlocks(newStatus == RecipeLogic.Status.WORKING);
        }
        for (MultiblockPartMachine part : getParts()) {
            part.recipeLogicStatusChanged(oldStatus, newStatus);
            MachineRenderState state = part.getRenderState();
            if (state.hasProperty(GTMachineModelProperties.RECIPE_LOGIC_STATUS)) {
                part.setRenderState(state.setValue(GTMachineModelProperties.RECIPE_LOGIC_STATUS, newStatus));
            }
        }
    }

    /**
     * If the multiblock should update all active blocks in its structure
     */
    public boolean shouldUpdateActiveBlocks() {
        return true;
    }

    @Override
    public boolean isRecipeLogicAvailable() {
        return isFormed && !getDefaultPatternState().hasErrors();
    }

    @Override
    public void afterWorking() {
        for (MultiblockPartMachine part : getParts()) {
            part.afterWorking(this);
        }
        IRecipeLogicMachine.super.afterWorking();
    }

    @Override
    public boolean beforeWorking(@Nullable GTRecipe recipe) {
        for (MultiblockPartMachine part : getParts()) {
            if (!part.beforeWorking(this)) {
                return false;
            }
        }
        return IRecipeLogicMachine.super.beforeWorking(recipe);
    }

    @Override
    public boolean onWorking() {
        for (MultiblockPartMachine part : getParts()) {
            if (!part.onWorking(this)) {
                return false;
            }
        }
        return IRecipeLogicMachine.super.onWorking();
    }

    public GTRecipeType getRecipeType() {
        int index = activeRecipeType >= 0 && activeRecipeType < recipeTypes.length ? activeRecipeType : 0;
        return recipeTypes[index];
    }

    public void cycleActiveRecipeType() {
        int newActiveRecipeType = (getActiveRecipeType() + 1) % recipeTypes.length;
        setActiveRecipeType(newActiveRecipeType);
        getRecipeLogic().updateTickSubscription();
    }

    /**
     * Sets a recipe type of the machine.
     * FOR INTERNAL / TESTING USE ONLY!
     * NOT SUPPORTED FOR PRODUCTION USE!
     *
     * @param newType The new recipe type
     */
    @ApiStatus.Internal
    @VisibleForTesting
    public void setRecipeType(GTRecipeType newType) {
        recipeTypes[activeRecipeType] = newType;
    }

    @Override
    public void setVoidingMode(VoidingMode mode) {
        voidingMode = mode;
        getRecipeLogic().updateTickSubscription();
    }

    @Override
    public List<IWidget> getWidgetsForDisplay(PanelSyncManager syncManager) {
        List<IWidget> widgets = super.getWidgetsForDisplay(syncManager);
        widgets.add(GTMultiblockTextUtil.addUnformedWarning(this, syncManager));
        widgets.add(GTMultiblockTextUtil.addProgressLine(this, syncManager));
        widgets.add(GTMultiblockTextUtil.addWorkingStatusLine(this, syncManager));
        widgets.addAll(GTMultiblockTextUtil.addRecipeFailReasonLines(this, syncManager));
        widgets.add(GTMultiblockTextUtil.addRecipeTypeField(this, syncManager));
        widgets.addAll(getDefinition().getAdditionalDisplay().apply(this, syncManager));
        widgets.add(GTMultiblockTextUtil.addParallelLine(this, syncManager));
        widgets.add(GTMultiblockTextUtil.addBatchModeLine(this, syncManager));
        widgets.add(GTMultiblockTextUtil.addSubtickParallelsLine(this, syncManager));
        widgets.add(GTMultiblockTextUtil.addTotalRunsLine(this, syncManager));
        widgets.add(GTMultiblockTextUtil.addOutputLines(this, syncManager));
        return widgets;
    }
}

package com.gregtechceu.gtceu.api.multiblock.pattern;

import com.gregtechceu.gtceu.GTCEu;
import com.gregtechceu.gtceu.api.multiblock.PredicateContext;
import com.gregtechceu.gtceu.api.multiblock.util.RelativeDirection;

import com.google.common.base.Preconditions;

import java.util.*;

public class BasicSliceStrategy extends SliceStrategy {

    protected static class MultiblockSlice {

        public int minRepeats;
        public int maxRepeats;
        public int startInclusive;
        public int endExclusive;
        public int actualRepeats;

        public MultiblockSlice(int minRepeats, int maxRepeats, int startInclusive, int endExclusive,
                               int actualRepeats) {
            this.minRepeats = minRepeats;
            this.maxRepeats = maxRepeats;
            this.startInclusive = startInclusive;
            this.endExclusive = endExclusive;
            this.actualRepeats = actualRepeats;
        }

        @Override
        public String toString() {
            return String.format("[min %s, max %s, startInc %s, endExc %s, actual %s]", minRepeats, maxRepeats,
                    startInclusive, endExclusive, actualRepeats);
        }
    }

    protected final List<MultiblockSlice> multiblockSlices = new ArrayList<>();
    protected final List<PatternSlice> slices = new ArrayList<>();
    protected final int[] result = new int[2];

    @Override
    public boolean check(PatternState state, boolean flip) {
        int offset = 0;
        for (var multiSlice : multiblockSlices) {
            int result = checkMultiSlice(state, multiSlice, offset, flip);
            if (result == -1) return false;
            offset += result;
        }
        return true;
    }

    public int getMultiSliceRepeats(int index) {
        return multiblockSlices.get(index).actualRepeats;
    }

    protected int checkMultiSlice(PatternState state, MultiblockSlice multiblockSlice, int offset, boolean flip) {
        int sliceOffset = 0;
        int temp = 0;
        PredicateContext context = state.getContext();
        for (int i = 1; i <= multiblockSlice.maxRepeats; i++) {
            for (int j = multiblockSlice.startInclusive; j < multiblockSlice.endExclusive; j++) {
                int res = checkRepeatSlice(state, j, offset + temp, flip);
                if (res == -1) {
                    if (i <= multiblockSlice.minRepeats) {
                        context.commitSliceErrors();
                        return -1;
                    }
                    // invalid, but within min/max repeats so may be valid overall
                    context.popSlice();
                    multiblockSlice.actualRepeats = i - 1;
                    return sliceOffset;
                }
                temp += res;
            }
            sliceOffset = temp;
        }

        multiblockSlice.actualRepeats = multiblockSlice.maxRepeats;
        return sliceOffset;
    }

    protected int checkRepeatSlice(PatternState state, int index, int offset, boolean flip) {
        PatternSlice slice = slices.get(index);
        PredicateContext context = state.getContext();
        for (int i = 1; i <= slice.maxRepeats; i++) {
            context.pushSlice();
            boolean res = checkSlice(state, index, offset + i - 1, flip);
            if (!res) {
                if (i <= slice.minRepeats) return -1;

                // invalid, but within min/max repeats so may be valid overall
                context.popSlice();
                return slices.get(index).actualRepeats = i - 1;
            }
            // valid slice, clear errors just in case
            context.clearErrors();
        }
        return slices.get(index).actualRepeats = slice.maxRepeats;
    }

    @Override
    protected void finish(int[] dimensions, RelativeDirection[] directions, List<PatternSlice> slices) {
        super.finish(dimensions, directions, slices);

        this.slices.addAll(slices);

        BitSet covered = new BitSet(slices.size());
        int sum = 0;
        for (var arr : multiblockSlices) {
            covered.set(arr.startInclusive, arr.endExclusive);
            sum += arr.endExclusive - arr.startInclusive;
        }

        if (sum != covered.cardinality()) {
            GTCEu.LOGGER.error("Overlapping multiblock slices. " +
                    "Multiblock has {} slices total but only {} distinct slices.", sum, covered.cardinality());
            multiSliceError();
        }
        if (sum > slices.size()) {
            GTCEu.LOGGER.error("multiSlices out of bounds. {} slices total but {} slices in multiSlices",
                    slices.size(), sum);
            multiSliceError();
        }

        int i = covered.nextClearBit(0);
        while ((i = covered.nextClearBit(i)) < slices.size()) {
            multiblockSlices.add(new MultiblockSlice(1, 1, i, i + 1, -1));
            covered.set(i);
        }

        multiblockSlices.sort(Comparator.comparingInt(a -> a.startInclusive));
    }

    protected void multiSliceError() {
        GTCEu.LOGGER.error(
                "multiSlices in the pattern, formatted as [minRepeats, maxRepeats, startInclusive, endExclusive, actualRepeats]");
        for (var arr : multiblockSlices) {
            GTCEu.LOGGER.error(arr.toString());
        }
        throw new IllegalStateException("Illegal multiSlices, see log above.");
    }

    public BasicSliceStrategy multiSlice(int min, int max, int from, int to) {
        Preconditions.checkArgument(max >= min, "max: %s is less than min: %s", max, min);
        Preconditions.checkArgument(from >= 0, "from argument is negative: %s", from);
        Preconditions.checkArgument(to > 0, "to argument is not positive: %s", to);
        multiblockSlices.add(new MultiblockSlice(min, max, from, to, -1));
        return this;
    }
}

package com.gregtechceu.gtceu.api.multiblock.pattern;

import com.gregtechceu.gtceu.api.multiblock.MultiPredicate;
import com.gregtechceu.gtceu.api.multiblock.OriginOffset;
import com.gregtechceu.gtceu.api.multiblock.PredicateContext;
import com.gregtechceu.gtceu.api.multiblock.PredicateResult;
import com.gregtechceu.gtceu.api.multiblock.util.RelativeDirection;

import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.state.BlockState;

import it.unimi.dsi.fastutil.chars.Char2ObjectMap;
import lombok.Getter;
import org.jetbrains.annotations.Nullable;

import java.util.*;

public class BlockPattern implements IBlockPattern {

    @Getter
    protected final RelativeDirection[] directions;

    // TODO: can this be removed? Multiblocks with repeatable isles can differ in sizes
    @Getter
    protected final int[] dimensions;
    @Getter
    protected final OriginOffset offset;

    protected final boolean hasStartOffset;
    @Getter
    protected final PatternSlice[] slices;
    @Getter
    protected final SliceStrategy sliceStrategy;
    @Getter
    protected final Char2ObjectMap<MultiPredicate> predicates;

    public BlockPattern(PatternSlice[] slices, SliceStrategy sliceStrategy,
                        int[] dimensions, RelativeDirection[] directions,
                        @Nullable OriginOffset offset, @Nullable OriginOffset anchorOffset,
                        Char2ObjectMap<MultiPredicate> predicates,
                        char centerChar) {
        this.slices = slices;
        this.sliceStrategy = sliceStrategy;
        this.dimensions = dimensions;
        this.directions = directions;
        this.predicates = predicates;
        hasStartOffset = offset != null;

        if (offset == null) {
            this.offset = new OriginOffset();
            legacyStartOffset(centerChar);
        } else {
            this.offset = offset;
        }

        if (anchorOffset != null) { // needs to be negative cause of double offsetting
            this.offset.move(RelativeDirection.FRONT, -anchorOffset.get(RelativeDirection.FRONT));
            this.offset.move(RelativeDirection.UP, -anchorOffset.get(RelativeDirection.UP));
            this.offset.move(RelativeDirection.LEFT, -anchorOffset.get(RelativeDirection.LEFT));
        }
    }

    private void legacyStartOffset(char center) {
        if (center == 0) return;
        for (int sliceI = 0; sliceI < dimensions[0]; sliceI++) {
            int[] res = slices[sliceI].firstInstanceOf(center);
            if (res != null) {
                moveOffset(directions[0], -sliceI);
                moveOffset(directions[1], -res[0]);
                moveOffset(directions[2], -res[1]);
                return;
            }
        }
        throw new IllegalStateException("Failed to find center symbol:  '" + center + "'");
    }

    @Override
    public void checkPatternFastAt(Level level, PatternState patternState, BlockPos centerPos, Direction frontFacing,
                                   Direction upwardsFacing, boolean allowsFlip) {
        if (!patternState.cache.isEmpty()) {
            boolean pass = true;
            BlockPos.MutableBlockPos mBlockPos = new BlockPos.MutableBlockPos();
            for (var entry : patternState.cache.long2ObjectEntrySet()) {
                BlockPos pos = mBlockPos.set(entry.getLongKey()).immutable();
                BlockState state = level.getBlockState(pos);

                if (state != entry.getValue().getBlockState()) {
                    pass = false;
                    break;
                }

                BlockEntity cachedBlockEntity = entry.getValue().getBlockEntity();

                if (cachedBlockEntity != null) {
                    BlockEntity be = level.getBlockEntity(pos);
                    if (be != cachedBlockEntity) {
                        pass = false;
                        break;
                    }
                }
            }

            if (pass) {
                if (patternState.hasErrors()) {
                    patternState.setState(PatternState.CheckState.INVALID_CACHED);
                } else {
                    patternState.setState(PatternState.CheckState.VALID_CACHED);
                }

                return;
            }
        }

        boolean valid = checkPatternAt(level, patternState, centerPos, frontFacing, upwardsFacing, false);
        if (valid) {
            // reaching here means the cache failed or was empty
            patternState.setState(PatternState.CheckState.VALID_UNCACHED);
            patternState.setFlipped(false);
            return;
        }

        if (allowsFlip && patternState.shouldCheckFlip()) {
            valid = checkPatternAt(level, patternState, centerPos, frontFacing, upwardsFacing, true);
        }
        if (!valid) {
            // maybe empty the block info part of the cache?
            patternState.setState(PatternState.CheckState.INVALID_UNCACHED);
            return;
        }

        patternState.setState(PatternState.CheckState.VALID_UNCACHED);
        patternState.setFlipped(true);
    }

    @Override
    public boolean checkPatternAt(Level level, PatternState patternState, BlockPos centerPos, Direction frontFacing,
                                  Direction upwardsFacing,
                                  boolean isFlipped) {
        Objects.requireNonNull(patternState, "PatternState not set");

        PredicateContext context = patternState.resetContext(true);

        // only try to clear the cache for structure checking mapping when checking the structure for unflipped
        // maybe switch to a multiblock state value instead?
        if (!isFlipped) {
            patternState.getCache().clear();
            // keep old errors if flipped
            patternState.clearErrors();
        }

        context.updateLevel(level);

        BlockPos.MutableBlockPos controllerPos = centerPos.mutable();

        // reset predicates for testing
        predicates.values().forEach(MultiPredicate::resetLogic);

        // handle slices
        sliceStrategy.setPattern(this);
        sliceStrategy.start(controllerPos, frontFacing, upwardsFacing);
        if (!sliceStrategy.check(patternState, isFlipped)) return false;

        // global min check
        for (MultiPredicate predicate : predicates.values()) {
            if (!predicate.postGlobalTest(context)) {
                context.commitSliceErrors();
                return false;
            }
        }

        patternState.clearErrors();
        return true;
    }

    /**
     * Checks a specific slice for validity
     *
     * @param controllerPos The position of the controller
     * @param frontFacing   The front facing of the controller
     * @param upwardsFacing The up facing of the controller
     * @param sliceIndex    The index of the slice, this is where the pattern is gotten from, treats repeatable slices
     *                      as only 1
     * @param sliceOffset   The offset of the slice, how much offset in sliceDir to check the blocks in world, for
     *                      example, if the first slice is repeated 2 times, sliceIndex is 1 while this is 2
     * @param flip          Whether to flip or not
     * @return True if the check passed
     */
    public boolean checkSlice(BlockPos.MutableBlockPos controllerPos, PatternState patternState, Direction frontFacing,
                              Direction upwardsFacing,
                              int sliceIndex, int sliceOffset, boolean flip) {
        Direction absoluteSlice = directions[0].getRelativeFacing(frontFacing, upwardsFacing, flip);
        Direction absoluteString = directions[1].getRelativeFacing(frontFacing, upwardsFacing, flip);
        Direction absoluteChar = directions[2].getRelativeFacing(frontFacing, upwardsFacing, flip);

        BlockPos.MutableBlockPos sliceStart = startPos(controllerPos, frontFacing, upwardsFacing, flip)
                .move(absoluteSlice, sliceOffset);

        BlockPos.MutableBlockPos stringStart = sliceStart.mutable();
        BlockPos.MutableBlockPos charPos = sliceStart.mutable();
        PatternSlice slice = slices[sliceIndex];

        PredicateContext context = patternState.getContext();
        context.clearLayerCounts();

        Set<MultiPredicate> visitedPredicates = new HashSet<>();
        for (int stringIdx = 0; stringIdx < dimensions[1]; stringIdx++) {
            for (int charIdx = 0; charIdx < dimensions[2]; charIdx++) {
                context.updatePos(charPos);
                MultiPredicate multiPredicate = predicates.get(slice.charAt(stringIdx, charIdx));

                if (!multiPredicate.isAny()) patternState.updateCache();

                // state check
                PredicateResult result = multiPredicate.getPredicateAtPos(context);

                // all predicates failed
                if (!result.hasMatched()) {
                    multiPredicate.onError(context);
                    // errors get committed in BasicSliceStrategy
                    return false;
                }

                // max count checks
                if (!result.testMaxCount(context)) {
                    // errors get committed in BasicSliceStrategy
                    return false;
                }

                visitedPredicates.add(multiPredicate);
                charPos.move(absoluteChar);
            }

            stringStart.move(absoluteString);
            charPos.set(stringStart);
        }

        // slice min check
        for (MultiPredicate predicate : visitedPredicates) {
            if (!predicate.postSliceTest(context)) {
                return false;
            }
        }

        return true;
    }

    public int getRepetitionCount(int sliceIndex) {
        return slices[sliceIndex].actualRepeats;
    }

    private BlockPos.MutableBlockPos startPos(BlockPos.MutableBlockPos controllerPos, Direction frontFacing,
                                              Direction upwardsFacing, boolean flip) {
        BlockPos.MutableBlockPos start = controllerPos.mutable();
        offset.apply(start, frontFacing, upwardsFacing, flip);
        return start;
    }
}

package com.gregtechceu.gtceu.api.multiblock.pattern;

import com.gregtechceu.gtceu.api.machine.multiblock.MultiblockControllerMachine;
import com.gregtechceu.gtceu.api.multiblock.MultiblockWorldSavedData;
import com.gregtechceu.gtceu.api.multiblock.PredicateContext;
import com.gregtechceu.gtceu.api.multiblock.error.PatternError;
import com.gregtechceu.gtceu.api.multiblock.util.BlockInfo;

import net.minecraft.core.BlockPos;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.block.state.BlockState;

import it.unimi.dsi.fastutil.longs.Long2ObjectMap;
import it.unimi.dsi.fastutil.longs.Long2ObjectOpenHashMap;
import lombok.Getter;
import lombok.Setter;
import org.jetbrains.annotations.ApiStatus;
import org.jetbrains.annotations.Nullable;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/*
 * Contains vital information to an instanced version of a structure pattern.
 */
public class PatternState {

    @Getter
    protected @Nullable BlockPos controllerPos;
    @Getter
    protected @Nullable MultiblockControllerMachine controller;
    @Getter
    @Setter
    protected boolean isFormed = false;
    @Getter
    protected volatile boolean isFlipped = false;
    @Setter
    @Getter
    protected boolean actualFlipped = false;
    @Setter
    protected boolean shouldUpdate = true;
    @Getter
    protected List<PatternError> errors = List.of();
    @Setter
    @Getter
    protected CheckState state = CheckState.UNINITIALIZED;
    @Getter
    protected final PredicateContext context = new PredicateContext(this);
    @Getter
    protected final Long2ObjectMap<BlockInfo> cache = new Long2ObjectOpenHashMap<>();

    public void setController(MultiblockControllerMachine controller, BlockPos controllerPos) {
        this.controller = controller;
        this.controllerPos = controllerPos;
    }

    @ApiStatus.Internal
    public void setFlipped(boolean flipped) {
        isFlipped = flipped;
    }

    public boolean shouldUpdate() {
        return shouldUpdate;
    }

    public boolean hasErrors() {
        return !this.errors.isEmpty();
    }

    public void clearErrors() {
        this.errors = List.of();
    }

    public PredicateContext resetContext(boolean withLayer) {
        this.context.reset();
        this.context.setCheckLayer(withLayer);
        return this.context;
    }

    /// usage intended for outside {@link BlockPattern}
    public void setError(PatternError error) {
        this.errors = List.of(error);
    }

    public void setErrors(List<PatternError> errors) {
        this.errors = Collections.unmodifiableList(errors);
    }

    public void appendError(PatternError error) {
        ArrayList<PatternError> errors = new ArrayList<>(this.errors);
        errors.add(error);
        setErrors(errors);
    }

    public void appendErrors(List<PatternError> errors) {
        ArrayList<PatternError> list = new ArrayList<>(this.errors);
        list.addAll(errors);
        setErrors(list);
    }

    public void onBlockStateChanged(BlockPos pos, BlockState oldState, BlockState newState) {
        if (!(getContext().getCurrentBlockInfo().getLevel() instanceof ServerLevel serverLevel)) return;
        if (pos.equals(controllerPos)) {
            if (controller != null && !newState.is(controller.getBlockState().getBlock())) {
                controller.invalidateStructure(MultiblockControllerMachine.DEFAULT_STRUCTURE);
                MultiblockWorldSavedData.getOrCreate(serverLevel).removeMapping(this);
            }
            // block other than controller changed
        } else if (controller != null) {
            // if the blocks that changed where active blocks changing state, don't bother rechecking
            if ((oldState.getBlock() == newState.getBlock()) &&
                    newState.getBlock() instanceof IStructureChangeIgnored &&
                    oldState.getBlock() instanceof IStructureChangeIgnored) {
                return;
            }

            for (var name : controller.getStructureNames()) {
                PatternState patternState = controller.checkStructurePattern(name);
                if (!patternState.hasErrors()) {
                    controller.formStructure(name);
                    // previous formation may not have added the full multiblock the saved data
                    // todo there's probably a better way to do this
                    MultiblockWorldSavedData.getOrCreate(serverLevel).addMapping(this);
                } else {
                    controller.invalidateStructure(name);
                    if (name.equals(MultiblockControllerMachine.DEFAULT_STRUCTURE)) {
                        MultiblockWorldSavedData.getOrCreate(serverLevel).removeMapping(this);
                        controller.checkAndFormStructure();
                    }
                }
            }
        }
    }

    protected void updateCache() {
        PredicateContext context = getContext();
        getCache().put(context.pos().asLong(), context.computeBlockInfo());
    }

    public boolean shouldCheckFlip() {
        return getContext().isCheckFlipped();
    }

    @Getter
    public enum CheckState {

        /**
         * The cache doesn't match with the structure's data. The structure has been rechecked from scratch, is valid,
         * and the cache is now populated.
         */
        VALID_UNCACHED(true, false),

        /**
         * The cache matches the structure's data.
         */
        VALID_CACHED(true, true),

        /**
         * The cache doesn't match with the structure's data. The structure has been rechecked from scratch, is invalid,
         * and the cache is now empty.
         */
        INVALID_CACHED(false, true),

        /**
         * The cache is empty. The structure has been rechecked from scratch and is invalid, the cache remains empty.
         */
        INVALID_UNCACHED(false, false),

        /**
         * The Check State is not initialized, structure checking failed
         */
        UNINITIALIZED(false, false);

        private final boolean valid;
        private final boolean cached;

        CheckState(boolean valid, boolean cached) {
            this.valid = valid;
            this.cached = cached;
        }
    }
}

package com.gregtechceu.gtceu.api.multiblock.pattern;

import com.gregtechceu.gtceu.api.multiblock.util.RelativeDirection;

import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;

import lombok.Getter;
import lombok.Setter;
import org.jetbrains.annotations.Nullable;

import java.util.List;

public abstract class SliceStrategy {

    protected final int[] dimensions = new int[3];
    protected final RelativeDirection[] directions = new RelativeDirection[3];

    @Getter
    @Setter
    private @Nullable BlockPattern pattern;
    private @Nullable BlockPos.MutableBlockPos pos;
    private @Nullable Direction front, up;

    public BlockPos.MutableBlockPos getPos() {
        if (pos == null) throw new IllegalStateException("SliceStrategy.start() has not been called");
        return pos;
    }

    public Direction getFront() {
        if (front == null) throw new IllegalStateException("SliceStrategy.start() has not been called");
        return front;
    }

    public Direction getUp() {
        if (up == null) throw new IllegalStateException("SliceStrategy.start() has not been called");
        return up;
    }

    /**
     * Checks the slices
     *
     * @param flip Whether this is a flipped pattern check.
     * @return Whether the pattern is formed after this.
     */
    public abstract boolean check(PatternState state, boolean flip);

    /**
     * Called at the start of a structure check.
     */
    protected void start(BlockPos.MutableBlockPos pos, Direction front, Direction up) {
        this.pos = pos;
        this.front = front;
        this.up = up;
    }

    /**
     * No more slices will be added. Check preconditions and throw exceptions here.
     */
    protected void finish(int[] dimensions, RelativeDirection[] directions, List<PatternSlice> slices) {
        System.arraycopy(dimensions, 0, this.dimensions, 0, 3);
        System.arraycopy(directions, 0, this.directions, 0, 3);
    }

    protected boolean checkSlice(PatternState state, int index, int offset, boolean flip) {
        if (pattern == null) throw new IllegalStateException("BlockPattern not set.");
        return pattern.checkSlice(getPos(), state, getFront(), getUp(), index, offset, flip);
    }
}

package com.gregtechceu.gtceu.api.multiblock.util;

import com.gregtechceu.gtceu.api.machine.multiblock.part.MultiblockPartMachine;
import com.gregtechceu.gtceu.utils.GTUtil;

import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.util.StringRepresentable;

import org.jetbrains.annotations.NotNull;

import java.util.Locale;
import java.util.function.BinaryOperator;
import java.util.function.ToIntFunction;

/**
 * Relative direction when facing horizontally and vertically
 */
public enum RelativeDirection implements StringRepresentable {

    UP((f, u) -> u),
    DOWN((f, u) -> u.getOpposite()),
    LEFT((f, u) -> GTUtil.cross(f, u).getOpposite()),
    RIGHT(GTUtil::cross),
    FRONT((f, u) -> f),
    BACK((f, u) -> f.getOpposite());

    private final BinaryOperator<Direction> facingFunction;

    public static final EnumCodec<RelativeDirection> CODEC = StringRepresentable
            .fromEnum(RelativeDirection::values);

    public static final RelativeDirection[] VALUES = values();

    RelativeDirection(BinaryOperator<Direction> facingFunction) {
        this.facingFunction = facingFunction;
    }

    public RelativeDirection getOpposite() {
        return VALUES[oppositeOrdinal()];
    }

    public int oppositeOrdinal() {
        return switch (ordinal()) {
            case 0 -> 1;
            case 1 -> 0;
            case 2 -> 3;
            case 3 -> 2;
            case 4 -> 5;
            case 5 -> 4;
            default -> throw new IllegalStateException("Unexpected value: " + ordinal());
        };
    }

    public Direction getRelativeFacing(Direction frontFacing, Direction upwardsFacing) {
        if (frontFacing.getAxis() == upwardsFacing.getAxis()) {
            return Direction.UP;
            // throw new IllegalArgumentException("front facing and up facing must be on different axes");
        }
        return facingFunction.apply(frontFacing, upwardsFacing);
    }

    public Direction getRelativeFacing(Direction frontFacing, Direction upwardsFacing, boolean isFlipped) {
        return (isFlipped && (this == LEFT || this == RIGHT)) ?
                getRelativeFacing(frontFacing, upwardsFacing).getOpposite() :
                getRelativeFacing(frontFacing, upwardsFacing);
    }

    public ToIntFunction<BlockPos> getPosSorter(Direction frontFacing, Direction upwardsFacing, boolean isFlipped) {
        // get the direction to go in for the part sorter
        Direction sorterDirection = getRelativeFacing(frontFacing, upwardsFacing, isFlipped);

        // Determined by Direction.Axis + Direction.AxisDirection
        return switch (sorterDirection) {
            case UP -> BlockPos::getY;
            case DOWN -> pos -> -pos.getY();
            case EAST -> BlockPos::getX;
            case WEST -> pos -> -pos.getX();
            case NORTH -> pos -> -pos.getZ();
            case SOUTH -> BlockPos::getZ;
        };
    }

    public ToIntFunction<MultiblockPartMachine> getMultiSorter(Direction frontFacing, Direction upwardsFacing,
                                                               boolean isFlipped) {
        // get the direction to go in for the part sorter
        Direction sorterDirection = getRelativeFacing(frontFacing, upwardsFacing, isFlipped);

        // Determined by Direction.Axis + Direction.AxisDirection
        return switch (sorterDirection) {
            case UP -> p -> p.getBlockPos().getY();
            case DOWN -> p -> -p.getBlockPos().getY();
            case EAST -> p -> p.getBlockPos().getX();
            case WEST -> p -> -p.getBlockPos().getX();
            case NORTH -> p -> -p.getBlockPos().getZ();
            case SOUTH -> p -> p.getBlockPos().getZ();
        };
    }

    /**
     * Simulates rotating the controller around an axis to get to a new front facing.
     *
     * @return Returns the new upwards facing.
     */
    public static Direction simulateAxisRotation(Direction newFrontFacing, Direction oldFrontFacing,
                                                 Direction upwardsFacing) {
        if (newFrontFacing.getAxis() == oldFrontFacing.getAxis()) return upwardsFacing;

        Direction cross = GTUtil.cross(newFrontFacing, oldFrontFacing);

        assert cross != null;
        if (cross.getAxis() == upwardsFacing.getAxis()) return upwardsFacing;

        if (oldFrontFacing.getClockWise(cross.getAxis()) == newFrontFacing)
            return oldFrontFacing.getOpposite();

        return oldFrontFacing;
    }

    /**
     * Offset a BlockPos relatively in any direction by any amount. Pass negative values to offset down, right or
     * backwards.
     */
    public static BlockPos offsetPos(BlockPos pos, Direction frontFacing, Direction upwardsFacing, boolean isFlipped,
                                     int upOffset, int leftOffset, int forwardOffset) {
        BlockPos.MutableBlockPos mbp = pos.mutable();
        mbp.move(UP.getRelativeFacing(frontFacing, upwardsFacing, isFlipped), upOffset);
        mbp.move(LEFT.getRelativeFacing(frontFacing, upwardsFacing, isFlipped), leftOffset);
        mbp.move(FRONT.getRelativeFacing(frontFacing, upwardsFacing, isFlipped), forwardOffset);
        return mbp.immutable();
    }

    public static <T extends Enum<T>> void validateFacingsArray(T[] facings) {
        if (facings.length != 3) throw new IllegalArgumentException("Facings must be array of length 3!");

        int c = 0;
        for (int i = 0; i < 3; i++) {
            c |= (1 << facings[i].ordinal() / 2);
        }

        if (c != 7) throw new IllegalArgumentException("The 3 facings must use each axis exactly once!");
    }

    /**
     * @param other The other direction to check
     * @return Whether both directions are on the same axis
     */
    public boolean isSameAxis(RelativeDirection other) {
        return (other.ordinal() ^ this.ordinal() & 0x01) != 0;
    }

    public static Direction getActualDirection(Direction original, Direction current, Direction direction) {
        return findRelativeOf(original, current).applyDirection(direction);
    }

    /**
     * Finds the difference of {@code baseDir} and {@code relativeDir} as a relative direction.
     * <br>
     * If {@code baseDir} is vertical (e.g. {@link Direction#UP UP} or {@link Direction#DOWN DOWN}),
     * the rotation is calculated with {@link Direction#NORTH NORTH} as the upwards direction.
     *
     * @param baseDir     the direction to offset
     * @param relativeDir the direction to offset by
     * @return The difference of {@code baseDir} and {@code relativeDir} as a relative direction
     */
    public static RelativeDirection findRelativeOf(Direction baseDir, Direction relativeDir) {
        return findRelativeOf(baseDir, relativeDir, Direction.UP);
    }

    /**
     * Finds the difference of {@code baseDir} and {@code relativeDir} as a relative direction.
     * <br>
     * If {@code baseDir} is vertical, the rotation is calculated with {@code upwardsDir} as the "upwards" direction.
     *
     * @param baseDir     the direction to offset
     * @param relativeDir the direction to offset by
     * @param upwardsDir  the upwards direction
     * @return The difference of {@code baseDir} and {@code relativeDir} as a relative direction
     */
    public static RelativeDirection findRelativeOf(Direction baseDir, Direction relativeDir, Direction upwardsDir) {
        // Check simple cases first
        if (baseDir == relativeDir) return RelativeDirection.FRONT;
        if (baseDir.getOpposite() == relativeDir) return RelativeDirection.BACK;

        if (baseDir.getAxis().isHorizontal()) { // baseDir is one of N,S,W,E
            if (relativeDir == Direction.UP) return RelativeDirection.UP;
            else if (relativeDir == Direction.DOWN) return RelativeDirection.DOWN;
            else if (relativeDir == baseDir.getCounterClockWise()) return RelativeDirection.LEFT;
            else return RelativeDirection.RIGHT; // getClockWise
        } else { // baseDir is UP or DOWN
            if (upwardsDir.getAxis() == Direction.Axis.Y) {
                throw new IllegalStateException("upwardsDir must be a horizontal direction! is " + upwardsDir);
            }

            if (relativeDir == upwardsDir.getCounterClockWise()) {
                return RelativeDirection.LEFT;
            } else if (relativeDir == upwardsDir.getClockWise()) {
                return RelativeDirection.RIGHT;
            } else { // relativeDir is NORTH or SOUTH (assuming upwardsDir is NORTH)
                RelativeDirection dir;
                if (relativeDir == upwardsDir.getOpposite()) dir = RelativeDirection.UP;
                else dir = RelativeDirection.DOWN; // relativeDir == NORTH

                if (baseDir == Direction.DOWN) dir = dir.getOpposite();
                return dir;
            }
        }
    }

    public Direction getDefaultFacing() {
        return switch (this) {
            case UP -> Direction.UP;
            case DOWN -> Direction.DOWN;
            case LEFT -> Direction.WEST;
            case RIGHT -> Direction.EAST;
            case FRONT -> Direction.NORTH;
            case BACK -> Direction.SOUTH;
        };
    }

    public Direction applyDirection(Direction dir) {
        return switch (this) {
            case UP -> dir.getAxis() == Direction.Axis.Y ? Direction.NORTH : Direction.UP;
            case DOWN -> dir.getAxis() == Direction.Axis.Y ? Direction.SOUTH : Direction.DOWN;
            case LEFT -> dir.getAxis().isHorizontal() ? dir.getCounterClockWise() :
                    dir.getAxisDirection().getStep() > 0 ? Direction.WEST : Direction.EAST;
            case RIGHT -> dir.getAxis().isHorizontal() ? dir.getClockWise() :
                    dir.getAxisDirection().getStep() > 0 ? Direction.EAST : Direction.WEST;
            case FRONT -> dir;
            case BACK -> dir.getOpposite();
        };
    }

    @Override
    public @NotNull String getSerializedName() {
        return name().toLowerCase(Locale.ROOT);
    }
}

